import { describe, expect, it } from 'vitest';
import fixtures from './fixtures/whist.json';
import { leaderSeat } from './standings';
import { bannedBet, bettingOrder, scoreWhistRound, validateWhistRound, whistRoundPlan, whistRoundScore } from './whist';

// Cases generated by the game (Tests/ScorekeeperFixtures.gd); the port must match all of them.
describe('Whist matches the game', () => {
  it.each(fixtures.roundPlans)('round plan for $players players (start with 8s: $startWithEights)', (c) => {
    expect(whistRoundPlan(c.players, c.startWithEights)).toEqual(c.plan);
  });
  it.each(fixtures.bannedBets)('banned bet with $cards cards after $bets', (c) => {
    expect(bannedBet(c.cards, c.bets)).toEqual(c.banned);
  });
  it('scores every bet/tricks combination', () => {
    for (const c of fixtures.roundScores) expect(whistRoundScore(c.bet, c.tricks)).toBe(c.score);
  });
  it.each(fixtures.winners)('winner of $scores', (c) => {
    expect(leaderSeat(c.scores)).toBe(c.winner);
  });
});

describe('Whist round entry', () => {
  it('rotates the first bettor every round', () => {
    expect(bettingOrder(0, 4)).toEqual([0, 1, 2, 3]);
    expect(bettingOrder(1, 4)).toEqual([1, 2, 3, 0]);
    expect(bettingOrder(2, 4, 3)).toEqual([1, 2, 3, 0]);
  });
  it('rejects the banned last bet and wrong trick totals', () => {
    const round = { bets: [1, 0, 1, 1], tricks: [1, 0, 1, 0] };
    // 3 cards, round 0: seat 3 bets last; others bet 2, so 1 is banned.
    expect(validateWhistRound(round, 3, 0)).toEqual([
      { kind: 'banned-bet', seat: 3, bet: 1 },
      { kind: 'tricks-total', expected: 3, actual: 2 },
    ]);
    expect(validateWhistRound({ bets: [1, 0, 1, 0], tricks: [1, 0, 1, 1] }, 3, 0)).toEqual([]);
  });
  it('scores a complete round only', () => {
    expect(scoreWhistRound({ bets: [1, 0, null], tricks: [1, 0, 0] })).toBeNull();
    expect(scoreWhistRound({ bets: [1, 0, 2], tricks: [1, 1, 2] })).toEqual([6, -1, 7]);
  });
});
